async function unzip(buffer){
 const b=new Uint8Array(buffer),v=new DataView(buffer);let end=-1;for(let i=b.length-22;i>=Math.max(0,b.length-65557);i--)if(v.getUint32(i,true)===0x06054b50){end=i;break;}
 if(end<0)throw Error('這不是可讀取的 .xlsx 檔案，或檔案已加密。');const count=v.getUint16(end+10,true);let at=v.getUint32(end+16,true);if(count>3000)throw Error('檔案內容太多，請拆分後上傳。');const entries=new Map();let expanded=0;
 for(let n=0;n<count;n++){if(at+46>b.length||v.getUint32(at,true)!==0x02014b50)throw Error('Excel 壓縮結構有誤。');const flags=v.getUint16(at+8,true),method=v.getUint16(at+10,true),size=v.getUint32(at+20,true),raw=v.getUint32(at+24,true),nl=v.getUint16(at+28,true),extra=v.getUint16(at+30,true),comment=v.getUint16(at+32,true),offset=v.getUint32(at+42,true);const name=new TextDecoder().decode(b.slice(at+46,at+46+nl));at+=46+nl+extra+comment;if(flags&1)throw Error('不支援加密 Excel，請先解除密碼。');expanded+=raw;if(raw>20000000||expanded>40000000)throw Error('解壓縮資料超過 40MB，請拆分檔案。');entries.set(name,{method,size,raw,offset});}
 return async name=>{const e=entries.get(name);if(!e)throw Error('Excel 缺少必要資料：'+name);const o=e.offset;if(o+30>b.length||v.getUint32(o,true)!==0x04034b50)throw Error('Excel 壓縮結構有誤。');const start=o+30+v.getUint16(o+26,true)+v.getUint16(o+28,true);if(start+e.size>b.length)throw Error('Excel 資料不完整。');let data=b.slice(start,start+e.size);if(e.method===8){if(typeof DecompressionStream==='undefined')throw Error('此瀏覽器不支援 Excel 解壓縮，請使用新版 Chrome 或 Edge。');const reader=new Blob([data]).stream().pipeThrough(new DecompressionStream('deflate-raw')).getReader();let total=0,parts=[];for(;;){const {value,done}=await reader.read();if(done)break;total+=value.length;if(total>e.raw||total>20000000){await reader.cancel();throw Error('Excel 解壓縮大小異常。');}parts.push(value);}data=new Uint8Array(total);let p=0;for(const a of parts){data.set(a,p);p+=a.length;}}else if(e.method!==0)throw Error('不支援此 Excel 壓縮格式。');if(data.length!==e.raw)throw Error('Excel 解壓縮資料不完整。');return new TextDecoder().decode(data);};
}
async function readXlsx(file){const read=await unzip(await file.arrayBuffer()),book=xml(await read('xl/workbook.xml')),rels=xml(await read('xl/_rels/workbook.xml.rels'));let shared=[];try{shared=nodes(xml(await read('xl/sharedStrings.xml')),'si').map(x=>nodes(x,'t').map(t=>t.textContent).join(''));}catch(e){if(!e.message.includes('缺少必要資料'))throw e;}
 const targets=new Map(nodes(rels,'Relationship').filter(x=>x.getAttribute('TargetMode')!=='External').map(x=>[x.getAttribute('Id'),x.getAttribute('Target')]));const result=[];
 for(const sh of nodes(book,'sheet')){if(result.length>=20)throw Error('最多支援 20 張工作表，請拆分檔案。');const id=sh.getAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships','id'),target=targets.get(id);if(!target)continue;const path=new URL(target,'https://xlsx.local/xl/workbook.xml').pathname.slice(1);const doc=xml(await read(path)),matrix=[];let cells=0;
 for(const row of nodes(doc,'row')){const rn=Number(row.getAttribute('r'));if(!Number.isInteger(rn)||rn<1||rn>20000)throw Error('工作表超過 20,000 列或列號不正確，請先拆分。');const values=[];for(const c of nodes(row,'c')){if(++cells>200000)throw Error('工作表超過 200,000 格，請拆分後上傳。');const ref=c.getAttribute('r')||'',letters=ref.match(/^[A-Z]+/);if(!letters)continue;let cn=0;for(const ch of letters[0])cn=cn*26+ch.charCodeAt(0)-64;if(cn>256)throw Error('最多支援 256 欄，請移除多餘欄位。');const type=c.getAttribute('t'),val=nodes(c,'v')[0]?.textContent??'';let value=type==='s'?(shared[Number(val)]??''):type==='inlineStr'?nodes(c,'t').map(t=>t.textContent).join(''):val;if(type==='e')value='[Excel錯誤] '+value;if(nodes(c,'f').length&&val==='')value='[公式無快取值]';values[cn-1]=value;}matrix[rn-1]=values;}result.push({name:sh.getAttribute('name'),matrix});}if(!result.length)throw Error('沒有找到可讀取的工作表。');return result;
}
function sheet(){return sheets[Number($('siSheet').value)];}
function detect(){check();if(imported)throw Error('此批已匯入，請查看庫存或選擇新的檔案。');const matrix=sheet().matrix,h=Number($('siHeader').value)-1;if(!Number.isInteger(h)||h<0||h>=100)throw Error('標題列請填 1 至 100。');const heads=matrix[h]||[];$('siMapping').open=false;groups=[];heads.forEach((v,i)=>{if(kind(v)==='name'){let location=-1,quantity=-1,unit=-1;for(let j=Math.max(0,i-1);j<=Math.min(heads.length-1,i+2);j++){const k=kind(heads[j]);if(k==='location')location=j;if(k==='quantity')quantity=j;if(k==='unit')unit=j;}groups.push({location,name:i,quantity,unit});}});if(!groups.length)groups.push({location:-1,name:-1,quantity:-1,unit:-1});mapping();$('siResult').hidden=true;}
function mapping(){const out=$('siGroups');out.replaceChildren();const heads=sheet().matrix[Number($('siHeader').value)-1]||[],cols=Math.max(heads.length,...sheet().matrix.slice(0,100).map(r=>r?.length||0));groups.forEach((g,i)=>{const box=el('div',undefined,'si-group'),top=el('div',undefined,'si-toolbar');top.append(el('b','第 '+(i+1)+' 組'));const del=el('button','移除此組','btn');del.onclick=()=>{check();if(imported)return;groups.splice(i,1);mapping();$('siResult').hidden=true;};top.append(del);box.append(top);const map=el('div',undefined,'si-map');for(const [key,label] of Object.entries({location:'位置欄',name:'品項欄（必選）',quantity:'數量欄（必選）',unit:'單位欄'})){const l=el('label',label),sel=el('select');sel.append(new Option('未提供／請選擇','-1'));for(let c=0;c<cols;c++)sel.append(new Option(col(c)+' · '+norm(heads[c]),String(c)));sel.value=String(g[key]);sel.dataset.field=key;sel.onchange=()=>{check();if(imported)return;g[key]=Number(sel.value);$('siResult').hidden=true;};l.append(sel);map.append(l);}box.append(map);out.append(box);});}
function issues(row){const a=[];if(!norm(row.location))a.push('位置待補');if(!norm(row.name))a.push('品項待補');const q=norm(row.quantity);if(q==='')a.push('數量空白');else if(!/^(?:\d+|\d{1,3}(?:,\d{3})+)(?:\.\d+)?$/.test(q)||!Number.isFinite(Number(q.replaceAll(',','')))||Number(q.replaceAll(',',''))>Number.MAX_SAFE_INTEGER)a.push('數量格式待確認');if(row.duplicate)a.push('同位置同名，請確認是否重複');if(Object.values(row).some(x=>typeof x==='string'&&/\[公式無快取值\]|\[Excel錯誤\]/.test(x)))a.push('來源公式或儲存格錯誤');return a;}
