  check();if(imported)throw Error('此批已匯入。');const row=processingRow;if(!row||processingEpoch!==epoch||!rows.includes(row))throw Error('預覽資料已更新，請關閉視窗後重新選擇。');
  for(const [key,id] of Object.entries(processFields))row[key]=norm($(id).value);
  duplicates();const remaining=issues(row),scroll=root.querySelector('.si-scroll'),top=scroll.scrollTop;
  processDialog.close();render();scroll.scrollTop=top;
