 if(selectedGroup!=='all')visible=visible.filter(r=>r.group===Number(selectedGroup));
 const natural=new Intl.Collator('zh-Hant',{numeric:true,sensitivity:'base'});
 visible=[...visible].sort((a,b)=>a.group-b.group||(a.location===''?1:0)-(b.location===''?1:0)||natural.compare(a.location,b.location)||a.originalRow-b.originalRow);
 const max=Math.max(1,Math.ceil(visible.length/40));page=Math.max(0,Math.min(page,max-1));const body=$('siRows');body.replaceChildren();let last='';
