$('siFile').onchange=async()=>{const token=++epoch;workingOwner='';sourceHash='';batchId='';imported=false;rows=[];sheets=[];$('siSetup').hidden=true;$('siResult').hidden=true;$('siError').textContent='';const file=$('siFile').files[0];if(!file)return;try{check();if(!/\.xlsx$/i.test(file.name))throw Error('本版支援 .xlsx；舊 .xls 或其他格式請先另存為 Excel 活頁簿。');if(file.size>5*1024*1024)throw Error('檔案超過 5MB，請拆分後上傳。');busy=true;workingOwner=ownerScope();batchId=crypto.randomUUID();fileName=file.name;$('siStatus').textContent='正在讀取 '+fileName+'…';const result=await readXlsx(file);const digest=await crypto.subtle.digest('SHA-256',await file.arrayBuffer());if(token!==epoch)return;check();sourceHash=Array.from(new Uint8Array(digest),b=>b.toString(16).padStart(2,'0')).join('');sheets=result;$('siSheet').replaceChildren(...sheets.map((s,i)=>new Option(s.name,String(i))));$('siSheet').value='0';$('siHeader').value='1';$('siSetup').hidden=false;autoPreview();}catch(e){if(token===epoch){$('siError').textContent=e.message;$('siStatus').textContent='未匯入，原有資料未變更。';}}finally{busy=false;}};
