function setupDefinitions(data){const definitions=data.locationSettings??[];if(!Array.isArray(definitions)||!definitions.every(d=>d&&typeof d.warehouse==='string'&&norm(d.warehouse)&&d.warehouse.length<=100&&(d.location===null||typeof d.location==='string'&&norm(d.location)&&d.location.length<=200)))throw Error('位置設定格式不正確，原資料已保留。');return definitions;}
// Location nature is explicitly configured; never infer it from Excel names.
const LOCATION_KINDS=['unknown','inside','outside'];
function locationKind(data,warehouse,location){const d=[...setupDefinitions(data)].reverse().find(d=>d.warehouse===warehouse&&d.location===location);if(d?.kind!==undefined&&!LOCATION_KINDS.includes(d.kind))throw Error('位置性質格式不正確，原資料已保留。');return d?.kind||'unknown';}
function locationKindLabel(kind){return {unknown:'待確認',inside:'倉庫內',outside:'倉庫外使用位置'}[kind]||'待確認';}
function transferDestinations(data,row){const sourceKind=locationKind(data,row.warehouse,row.location),result=[];for(const [warehouse,positions] of setupGroups(data))for(const location of positions.keys()){if(!location||(warehouse===row.warehouse&&location===row.location))continue;const targetKind=locationKind(data,warehouse,location);let note='',blocked=false;if(sourceKind==='unknown'||targetKind==='unknown'||!row.location)note='移轉適用性待確認';else if(sourceKind==='inside'&&targetKind==='outside'){note='請用領用單';blocked=true;}else if(sourceKind==='outside'&&targetKind==='inside'){note='請走歸還流程';blocked=true;}result.push({warehouse,location,token:JSON.stringify([warehouse,location]),note,blocked});}return result.sort((a,b)=>locationCompare(a.warehouse,b.warehouse)||locationCompare(a.location,b.location));}
function validateTransferDestination(data,row,warehouse,location){if(!row.location||!location||!setupGroups(data).get(warehouse)?.has(location))throw Error('請選擇已建立的目標位置。');if(row.warehouse===warehouse&&row.location===location)throw Error('目標位置不可與原位置相同。');const sourceKind=locationKind(data,row.warehouse,row.location),targetKind=locationKind(data,warehouse,location);if(sourceKind==='unknown'||targetKind==='unknown')throw Error('請先由管理者確認原位置及目標位置的性質。');if(sourceKind==='inside'&&targetKind==='outside')throw Error('從倉庫領到 N櫃或其他倉庫外位置，請使用領用單。');if(sourceKind==='outside'&&targetKind==='inside')throw Error('送回倉庫須走歸還流程，先送待驗區。');return {sourceKind,targetKind};}
function setupGroups(data){const groups=locationGroups(data.batches.flatMap(b=>b.rows));for(const d of setupDefinitions(data)){if(!groups.has(d.warehouse))groups.set(d.warehouse,new Map());if(d.location!==null&&!groups.get(d.warehouse).has(d.location))groups.get(d.warehouse).set(d.location,[]);}return groups;}
