 const key=inventoryKey();await locked(key,()=>{
 if(!settingsAuthorized()||ownerScope()!==target.scope||positionTarget!==target||!positionDialog.open)throw Error('操作已取消或登入身分已變更。');if(localStorage.getItem(key)!==target.raw)throw Error('資料已由其他操作更新，請關閉視窗後重新開啟。');const data=readInventory(),positions=setupGroups(data).get(target.warehouse);if(!positions?.has(target.location))throw Error('位置已變更，請重新開啟。');if([...positions.keys()].some(v=>v!==target.location&&definitionName(v)===definitionName(name)))throw Error('此倉別已有相同名稱的位置。');if(name===target.location){positionMode(false);return;}
 const definitions=setupDefinitions(data).map(d=>({...d}));let affected=0;for(const batch of data.batches)for(const row of batch.rows)if(row.warehouse===target.warehouse&&row.location===target.location){row.location=name;affected++;}for(const d of definitions)if(d.warehouse===target.warehouse&&d.location===target.location)d.location=name;definitions.push({...definitions.find(d=>d.warehouse===target.warehouse&&d.location===name),warehouse:target.warehouse,location:name});
 const identities=new Set();for(const batch of data.batches)for(const row of batch.rows){const identity=stockIdentity(row);if(identities.has(identity))throw Error('修改後會出現同位置、同品項的重複資料，請改用其他名稱。');identities.add(identity);}if(data.locationSettingHistory!==undefined&&!Array.isArray(data.locationSettingHistory))throw Error('設定異動紀錄格式不正確，原資料已保留。');const p=actor();data.locationSettings=[...new Map(definitions.map(d=>[JSON.stringify([d.warehouse,d.location]),d])).values()];data.locationSettingHistory=[...(data.locationSettingHistory||[]),{at:new Date().toISOString(),actorId:p.id,actorName:p.name||p.account||'操作人員',action:'renameLocation',before:{warehouse:target.warehouse,location:target.location},after:name,affectedRows:affected}];writeLocal(key,JSON.stringify(data));target.location=name;target.raw=localStorage.getItem(key);renderSettings();positionMode(false);sp('spNote').textContent='已儲存位置名稱，共 '+target.count+' 筆品項，數量不變。';sp('spEdit').focus();
 });
