function categoryDayChoices(hostId,rule,selected=[]){const host=cf(hostId);host.replaceChildren();const weekly=rule==='weekly',length=weekly?7:31;for(let n=1;n<=length;n++){const label=el('label',undefined,'sc-check'),input=el('input');input.type='checkbox';input.value=String(n);input.checked=selected.includes(n);input.setAttribute('aria-label',weekly?'星期'+['一','二','三','四','五','六','日'][n-1]:n+' 日');label.append(input,document.createTextNode(weekly?'週'+['一','二','三','四','五','六','日'][n-1]:String(n)));host.append(label);}if(!weekly)host.append(el('p','每月 29～31 日遇當月無該日期時的處理方式，待正式排程規則確認；目前只儲存設定。','sc-note'));}
