async function saveCategory(event){event.preventDefault();if(categorySaving)return;categorySaving=true;cf('cfSave').disabled=true;try{const t=categoryTarget,value=categoryFormValue();if(!t||t.mode!=='edit')throw Error('請重新開啟分類視窗。');await locked(t.key,()=>{if(!categoriesAuthorized()||ownerScope()!==t.scope||categoryKey()!==t.key||!categoryDialog.open||categoryTarget!==t)throw Error('操作已取消或登入權限已變更。');if(localStorage.getItem(t.key)!==t.raw)throw Error('分類資料已由其他操作更新，請關閉後重新開啟。');const d=readCategories(),old=t.id?d.categories.find(c=>c.id===t.id):null;if(t.id&&!old)throw Error('找不到原分類，請重新讀取。');validateCategory(value,d,t.id,old?old.active:true);const now=new Date().toISOString(),user=actor(),item={...old,...value,id:old?.id||crypto.randomUUID(),active:old?old.active:true,createdAt:old?.createdAt||now,updatedAt:now};if(old)d.categories=d.categories.map(c=>c.id===old.id?item:c);else d.categories.push(item);d.history.push({id:crypto.randomUUID(),action:old?'edit':'create',categoryId:item.id,before:old||null,after:{...item},actorId:user.id,actorName:user.name||user.account||'操作人員',at:now});try{localStorage.setItem(t.key,JSON.stringify(d));}catch{throw Error('分類儲存失敗，請檢查瀏覽器空間與儲存權限；原分類資料未覆蓋。');}});categoryDialog.close();renderCategories();sc('scStatus').textContent='已儲存分類於此瀏覽器；正式 API 與品項連動尚未串接。';}catch(error){cf('cfError').textContent=error.message;}finally{categorySaving=false;cf('cfSave').disabled=false;}}
