function openCategoryState(id,trigger){try{if(!categoriesAuthorized())throw Error('目前帳號沒有分類管理權限。');const d=readCategories(),c=d.categories.find(x=>x.id===id);if(!c)throw Error('分類已變更，請重新讀取。');categoryStateTarget={id,active:!c.active,scope:ownerScope(),key:categoryKey(),raw:localStorage.getItem(categoryKey())};categoryStateFocus=trigger;cs('csTitle').textContent=(c.active?'停用':'啟用')+'分類：'+c.name;cs('csNote').textContent=c.active?'分類與歷史資料會保留。正式品項串接後，停用分類將不可新增新品項。若仍有啟用中的子分類，請先處理子分類。':'啟用後可使用此分類設定；子分類必須有啟用中的主分類。';cs('csError').textContent='';categoryStateDialog.showModal();cs('csCancel').focus();}catch(error){sc('scError').textContent=error.message;}}
